// src/App.jsx
import React, { useState, useEffect } from 'react';
import TaskList from './components/TaskList';
import AddTaskForm from './components/AddTaskForm';
import FilterControls from './components/FilterControls';
import Stats from './components/Stats';
import {
  getTasks,
  addTaskAPI,
  updateTaskAPI,
  deleteTaskAPI,
} from './api/taskService';

const App = () => {
  const [tasks, setTasks] = useState([]);
  const [filter, setFilter] = useState('all');
  const [loading, setLoading] = useState(true);

  // Fetch tasks from the mock API when the component mounts
  useEffect(() => {
    const loadTasks = async () => {
      try {
        const apiTasks = await getTasks();
        setTasks(apiTasks);
      } catch (error) {
        console.error("Failed to load tasks:", error);
        // Optional: Load from local storage as a fallback if API fails
        const savedTasks = localStorage.getItem('tasks');
        if (savedTasks) {
          setTasks(JSON.parse(savedTasks));
        }
      } finally {
        setLoading(false);
      }
    };
    loadTasks();
  }, []);

  // Handler to add a new task
  const addTask = async (title) => {
    if (!title.trim()) {
      alert('Task name cannot be empty!');
      return;
    }
    // Create a temporary ID, a real API would return the full object
    const newTaskData = { id: Date.now(), title, completed: false };
    
    // Optimistic UI update
    setTasks((prevTasks) => [...prevTasks, newTaskData]);

    try {
      await addTaskAPI(newTaskData);
    } catch (error) {
      console.error("Failed to add task:", error);
      // Revert state if API call fails
      setTasks((prevTasks) => prevTasks.filter((task) => task.id !== newTaskData.id));
    }
  };

  // Handler to toggle task completion
  const toggleTaskCompletion = async (id) => {
    const taskToUpdate = tasks.find((task) => task.id === id);
    if (!taskToUpdate) return;
    
    const updatedTask = { ...taskToUpdate, completed: !taskToUpdate.completed };

    // Optimistic UI update
    setTasks((prevTasks) =>
      prevTasks.map((task) => (task.id === id ? updatedTask : task))
    );

    try {
      await updateTaskAPI(id, { completed: updatedTask.completed });
    } catch (error) {
      console.error("Failed to update task:", error);
      // Revert state if API call fails
      setTasks((prevTasks) =>
        prevTasks.map((task) => (task.id === id ? taskToUpdate : task))
      );
    }
  };

  // Handler to delete a task
  const deleteTask = async (id) => {
    const tasksBeforeDelete = tasks;
    // Optimistic UI update
    setTasks((prevTasks) => prevTasks.filter((task) => task.id !== id));
    
    try {
      await deleteTaskAPI(id);
    } catch (error) {
      console.error("Failed to delete task:", error);
      // Revert state if API call fails
      setTasks(tasksBeforeDelete);
    }
  };

  // Handler to edit a task's title
  const editTask = async (id, newTitle) => {
    const taskToUpdate = tasks.find((task) => task.id === id);
    if (!taskToUpdate) return;

    const updatedTask = { ...taskToUpdate, title: newTitle };

    // Optimistic UI update
    setTasks((prevTasks) =>
      prevTasks.map((task) => (task.id === id ? updatedTask : task))
    );
    
    try {
      await updateTaskAPI(id, { title: newTitle });
    } catch (error) {
      console.error("Failed to edit task:", error);
       // Revert state if API call fails
      setTasks((prevTasks) =>
        prevTasks.map((task) => (task.id === id ? taskToUpdate : task))
      );
    }
  };

  // --- Derived State and UI Logic ---

  // Calculate counts for Stats and FilterControls
  const totalTasks = tasks.length;
  const completedTasks = tasks.filter((task) => task.completed).length;
  const incompleteTasks = totalTasks - completedTasks;

  // Filter tasks based on the current filter state
  const filteredTasks = tasks.filter((task) => {
    if (filter === 'completed') return task.completed;
    if (filter === 'incomplete') return !task.completed;
    return true; // 'all'
  });

  return (
    <div className="bg-gray-50 min-h-screen font-sans text-gray-800">
      <div className="container mx-auto p-4 sm:p-6 lg:p-8 max-w-4xl">
        <header className="mb-8">
          <h1 className="text-4xl font-bold">Task Manager</h1>
          <p className="text-gray-500 mt-1">Organize your tasks efficiently</p>
        </header>

        {loading ? (
          <div className="text-center text-gray-500 py-10">Loading tasks...</div>
        ) : (
          <main className="space-y-6">
            {/* Corrected Component Names and Props */}
            <Stats
              total={totalTasks}
              completed={completedTasks}
              incomplete={incompleteTasks}
            />

            <AddTaskForm onAddTask={addTask} />

            <div className="bg-white rounded-xl shadow-sm p-6">
              <h2 className="text-2xl font-bold mb-4">Filter Tasks</h2>
              <FilterControls
                currentFilter={filter}
                onSetFilter={setFilter}
                counts={{
                  all: totalTasks,
                  completed: completedTasks,
                  incomplete: incompleteTasks,
                }}
              />
              <hr className="my-6" />
              <h2 className="text-2xl font-bold mb-4 capitalize">{filter} Tasks</h2>
              <TaskList
                tasks={filteredTasks}
                onToggleComplete={toggleTaskCompletion}
                onDelete={deleteTask}
                onEdit={editTask}
              />
            </div>
          </main>
        )}
      </div>
    </div>
  );
};

export default App;
